$_MODULE['<{priceandorder}prestashop>_settings_c9cc8cce247e49bae79f15173ce97354'] = 'Enregistrer';
$_MODULE['<{priceandorder}prestashop>_tutorial_cb59b87e00d11222bfd9159d0d23836f'] = 'Premiers pas';
$_MODULE['<{priceandorder}prestashop>_tutorial_ea67abf8988cbc6b378a032f822801f8'] = 'Ouvrez l\'onglet Paramètres et saisissez la ou les adresses e-mail qui doivent recevoir les demandes de devis.';
$_MODULE['<{priceandorder}prestashop>_tutorial_7f1b3b7557f81bb527614a601f1df990'] = 'Choisissez quels champs facultatifs demander aux visiteurs (adresse, téléphone, quantité...).';
$_MODULE['<{priceandorder}prestashop>_tutorial_cc3b0858bf5fcf55dc3e1daae0076461'] = 'Allez dans Apparence > Positions dans votre back-office et assurez-vous que Priceandorder est activé sur le hook \"Colonne gauche\" ou \"Colonne droite\" pour afficher le formulaire latéral, et sur \"Pied de page\" pour le bouton flottant.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Envoyez une demande test depuis votre boutique et vérifiez qu\'elle arrive dans l\'onglet Demandes de devis et dans votre boîte mail.';
$_MODULE['<{priceandorder}prestashop>_tutorial_9ffdb95250e26c7a6b468126ac7c75b0'] = 'Comment ça marche';
$_MODULE['<{priceandorder}prestashop>_tutorial_813ce2687d65c0253de66d80cddab8f3'] = 'Le bloc latéral et le bouton flottant partagent le même formulaire ; un visiteur peut utiliser l\'un ou l\'autre.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bc9e9fef06497c843ddb85f457c24635'] = 'Les clients connectés ne sont jamais invités à indiquer leur nom ou leur e-mail &mdash; les informations de leur compte sont utilisées automatiquement.';
$_MODULE['<{priceandorder}prestashop>_tutorial_fe920a7d738e80a23e8675183ec4450d'] = 'Chaque envoi est enregistré dans l\'onglet Demandes de devis même si l\'e-mail de notification échoue, pour que rien ne soit perdu.';
$_MODULE['<{priceandorder}prestashop>_tutorial_bd4b0999a932632905b77cd2fbc0a97c'] = 'La protection anti-spam est automatique : un champ piège caché et une courte vérification de délai bloquent silencieusement les envois automatisés, et pas plus de 5 demandes par heure ne sont acceptées du même visiteur. Il n\'y a rien à résoudre pour un vrai visiteur.';
$_MODULE['<{priceandorder}prestashop>_tutorial_e41d93a6e7c1aa5aab80cb4cab9dc886'] = 'Une carte de notification apparaît sur votre Tableau de bord dès qu\'il y a de nouvelles demandes, avec un lien direct vers cet onglet Demandes de devis. Elle disparaît dès que chaque nouvelle demande est marquée comme traitée ou supprimée.';
$_MODULE['<{priceandorder}prestashop>_tutorial_231cf4c70d866b616c21baddaeed0696'] = 'Dépannage';
$_MODULE['<{priceandorder}prestashop>_tutorial_958aae0a194da728c36d3e7221675a84'] = 'Le formulaire n\'apparaît pas sur la boutique.';
$_MODULE['<{priceandorder}prestashop>_tutorial_babc3ee2827d2d3ae2ea9f8800c92452'] = 'Allez dans Apparence > Positions dans le back-office, recherchez \"priceandorder\" et vérifiez qu\'il est bien rattaché à un hook de colonne (latéral) ou au hook de pied de page (bouton flottant), et que votre thème actuel affiche bien ce hook (certains thèmes suppriment la colonne gauche/droite).';
$_MODULE['<{priceandorder}prestashop>_tutorial_106e29c08b607e3b79c61dc35b0289a7'] = 'Je ne reçois pas les e-mails de demande de devis.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0335b6ca536d6d636bdf088442b44790'] = 'Vérifiez les fautes de frappe dans l\'adresse du destinataire dans Paramètres, vérifiez votre dossier spam, et confirmez que l\'envoi d\'e-mails fonctionne en testant un autre module ou Paramètres avancés > E-mail. Chaque demande est de toute façon enregistrée dans l\'onglet Demandes de devis, vous pourrez donc toujours la retrouver là.';
$_MODULE['<{priceandorder}prestashop>_tutorial_487e540af0ce1574b40b98daaf9a704e'] = 'Un visiteur dit que le formulaire a rejeté son envoi.';
$_MODULE['<{priceandorder}prestashop>_tutorial_46ec8e9cec078e1824c2285289a9845a'] = 'Il s\'agit presque toujours de la protection anti-spam automatique : envoi du formulaire moins de 3 secondes après le chargement de la page, envoi plus d\'une heure après le chargement, ou plus de 5 demandes en une heure depuis la même connexion. Demandez-leur de recharger la page et de réessayer.';
$_MODULE['<{priceandorder}prestashop>_tutorial_f9459c8296e5294ec5990a767724198b'] = 'Les liens Conditions Générales / Politique de Confidentialité sont manquants ou incorrects.';
$_MODULE['<{priceandorder}prestashop>_tutorial_13dabddb6263b6457635e4c5d2035082'] = 'Définissez-les explicitement dans Paramètres. Si le lien Conditions est laissé vide, la page CMS des Conditions Générales de votre boutique est utilisée automatiquement ; si le lien Confidentialité est laissé vide, il n\'est simplement pas affiché.';
$_MODULE['<{priceandorder}prestashop>_tutorial_738cfeba525f1715b35cdbae92e826d9'] = 'Mon image promotionnelle semble déformée ou est rejetée.';
$_MODULE['<{priceandorder}prestashop>_tutorial_a7821d5fcb146c5ad0b90884e504d314'] = 'Les envois sont limités aux fichiers JPG, PNG, GIF ou WEBP jusqu\'à 4 Mo et sont automatiquement redimensionnés pour tenir dans 400x280 px en conservant leurs proportions, le fichier n\'est donc jamais déformé.';
$_MODULE['<{priceandorder}prestashop>_tutorial_6d08bb064fa0dc50df631711d8f9a10a'] = 'La carte de notification du Tableau de bord n\'apparaît pas.';
$_MODULE['<{priceandorder}prestashop>_tutorial_c0ce395b371236535761772d3eed1602'] = 'Vérifiez dans Apparence > Positions le hook dashboardZoneOne et assurez-vous que priceandorder y est aussi rattaché et activé &mdash; il est contrôlé séparément du formulaire de la boutique et n\'apparaît que sur la vraie page du Tableau de bord. La carte ne s\'affiche que tant qu\'au moins une demande est encore marquée \"Nouveau\".';
$_MODULE['<{priceandorder}prestashop>_tutorial_775956a2316b82459c84f10d788864d5'] = 'Besoin d\'aide supplémentaire ? Contactez';
